        self.assertEqual(run(['3', '1', '2']), {'n': 3, 'mean': 1.0, 'max': 1, 'flags': ['max', 'n']})
    def test_case_01(self):
        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 4, 'mean': 1.25, 'max': 2, 'flags': ['max', 'n']})
    def test_case_02(self):
        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 3, 'mean': 1.3333333333333333, 'max': 2, 'flags': ['max', 'n']})
