        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 3, 'mean': 3.0, 'max': 3, 'flags': ['max', 'n']})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'mean': 1.6666666666666667, 'max': 2, 'flags': ['max', 'n']})
