        self.assertEqual(run(['0']), {'n': 1, 'mean': 1.0, 'max': 1, 'flags': ['max', 'n']})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'mean': 1.0, 'max': 1, 'flags': ['max', 'n']})
